import { useRef, useState } from "react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Card } from "@atlas/ui-web/compositions/Card/Card"
import { ListItem, ListItemContent, ListItemTitle, ListItemDescription, ListItemActions } from "@atlas/ui-web/compositions/ListItem/ListItem"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Progress } from "@atlas/ui-web/primitives/Progress/Progress"

type FileStatus = "uploading" | "done" | "failed" | "rejected"
type UploadFile = { id: string; name: string; progress: number; status: FileStatus; retrying?: boolean; reason?: string }

export function FileUpload({ files, announcement, onAdd, onRetry, onRetryAll, onRemove }:
  { files: UploadFile[]; announcement: string; onAdd: (picked: File[]) => void; onRetry: (id: string) => void; onRetryAll: () => void; onRemove: (id: string) => void }) {
  const input = useRef<HTMLInputElement>(null)
  const [over, setOver] = useState(false)
  // A rejected file cannot be retried (the same file fails again); only a transient failure can.
  const retryable = files.filter((f) => f.status === "failed")
  const notUploaded = files.filter((f) => f.status === "failed" || f.status === "rejected")

  return (
    <div style={{ display: "grid", gap: "var(--atlas-spacing-4)" }}>
      <div
        onDragOver={(e) => { e.preventDefault(); setOver(true) }}
        onDragLeave={() => setOver(false)}
        onDrop={(e) => { e.preventDefault(); setOver(false); onAdd(Array.from(e.dataTransfer.files)) }}>
        <Card variant="outlined" selected={over}>
          <div style={{ display: "grid", justifyItems: "center", gap: "var(--atlas-spacing-2)", textAlign: "center" }}>
            <p style={{ fontSize: "var(--atlas-text-body)", color: "var(--atlas-foreground)" }}>Drag files here, or</p>
            <input ref={input} type="file" multiple hidden accept=".pdf,.png,.jpg" aria-describedby="upload-limits"
              onChange={(e) => { onAdd(Array.from(e.target.files ?? [])); e.target.value = "" }} />
            <Button variant="outline" onClick={() => input.current?.click()}>Choose files</Button>
            <p id="upload-limits" style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
              PDF, PNG or JPG, up to 10 MB each.
            </p>
          </div>
        </Card>
      </div>

      {notUploaded.length > 1 && (
        <Alert variant="danger" title={`${notUploaded.length} files didn't upload`}
          description="Your other files are kept. Retry the ones that lost connection, or remove the rest."
          actions={retryable.length > 0 && <Button size="sm" variant="primary" onClick={onRetryAll}>Retry all</Button>} />
      )}

      <ul aria-label="Files" style={{ display: "grid", gap: "var(--atlas-spacing-2)", listStyle: "none", margin: 0, padding: 0 }}>
        {files.map((f) => (
          <ListItem as="li" key={f.id} variant="outline" size="sm">
            <ListItemContent>
              <ListItemTitle>{f.name}</ListItemTitle>
              {f.status === "uploading" && <Progress aria-label={`Uploading ${f.name}`} value={f.progress} valueLabel={`${f.progress}%`} />}
              {(f.status === "failed" || f.status === "rejected") && <ListItemDescription>{f.reason}</ListItemDescription>}
            </ListItemContent>
            <ListItemActions>
              {f.status === "done" && <Badge variant="success" size="sm">Uploaded</Badge>}
              {(f.status === "failed" || f.status === "rejected") && <Badge variant="danger" size="sm">Failed</Badge>}
              {f.status === "failed" && (
                <Button size="sm" variant="outline" loading={f.retrying} aria-label={`Retry ${f.name}`} onClick={() => onRetry(f.id)}>Retry</Button>
              )}
              <Button size="sm" variant="ghost" aria-label={`${f.status === "uploading" ? "Cancel" : "Remove"} ${f.name}`} onClick={() => onRemove(f.id)}>
                {f.status === "uploading" ? "Cancel" : "Remove"}
              </Button>
            </ListItemActions>
          </ListItem>
        ))}
      </ul>

      {/* One polite live region: completion and failure only, never each percentage. */}
      <div role="status" aria-live="polite" style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>
        {announcement}
      </div>
    </div>
  )
}

